include <robotics.scad>
// Garmin LIDAR-Lite v3HP housing. Origin: base centre, floor z=0. Lenses face -Y, mounting flange at +Y.
W = 54.99;  H = 40.18;  D = 35;      // envelope (items 1, 6, 9)
hx = 36/2;  hz = 32/2;               // hole rectangle (items 2, 5)
hole_d = 4;                          // item 7
ear_r = H/2 - hz;                    // 4.09, lobe radius derived from envelope
lens_dx = 27.69/2;  lens_d = 14.65;  // items 3, 8; optical axis at mid-height (item 4: 16 below top holes)
flange_t = 3.0;                      // NOT dimensioned (scaled from side view)
body_h = 24;                         // NOT dimensioned (scaled from front view)
body_r = 4;                          // plain corner radius
lens_seat = 1.5;                     // bore depth for lens window
zc = H/2;
$fn = 48;

module body2d(w, h, r) rect([w, h], rounding = r);
module flange2d() union() {
  body2d(W, body_h, body_r);
  for (sx = [-1, 1], sz = [-1, 1]) hull() {
    translate([sx*hx, sz*hz]) circle(r = ear_r);
    translate([sx*(hx - 6), sz*(hz - 8)]) circle(r = ear_r);
  }
}
// map 2D (x, y) -> world (X, Z); extrude from y0 toward -Y by t
module slab(y0, t) translate([0, y0, zc]) xrot(90) linear_extrude(height = t) children();

difference() {
  union() {
    slab(D/2, flange_t) flange2d();                       // rear mounting flange with 4 ear lobes
    hull() {                                              // body, plain gentle taper toward front
      slab(D/2 - flange_t + 0.01, 0.01) body2d(W, body_h, body_r);
      slab(-D/2 + 0.01, 0.01) body2d(W - 2, body_h - 2, body_r + 1);
    }
  }
  // mounting holes, through flange
  for (sx = [-1, 1], sz = [-1, 1])
    translate([sx*hx, D/2 - flange_t/2, zc + sz*hz]) ycyl(d = hole_d, h = flange_t + 1);
  // lens window seats
  for (sx = [-1, 1])
    translate([sx*lens_dx, -D/2 + lens_seat/2 - 0.01, zc]) ycyl(d = lens_d, h = lens_seat + 0.02);
}

include <robotics.scad>
// Optic window, origin at its front face centre; axis along Y. Plain disc (thickness not dimensioned).
ycyl(d = 14.65, h = 1.0, anchor = FRONT, $fn = 64);

